mapper.select:
SELECT *
FROM user_point_records
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT COALESCE(SUM(points), 0)
FROM user_point_records
WHERE user_id = #{userId}
  AND change_type = #{changeType}
  AND points > 0
  AND created_at >= #{start}
  AND created_at < #{end}
